from textlesson import build
S=dict(cls=7,subj="science",subj_file="science")
build(dict(S,ch="the-ever-evolving-world-of-science",topic="how-science-grows",name_en="How science grows",name_ta="அறிவியல் எவ்வாறு வளர்கிறது",
 objectives=["Say that science grows by questions, tests and new tools","Give examples of scientific thinking"],
 story=("The curious boy","Ravi saw that the Moon looked bigger near the horizon and asked, \"Is it really bigger?\"\nHe held a coin at arm's length against the Moon at both times. The coin covered the Moon the same way each time.\n\"It only looks bigger,\" he said. \"I tested it myself.\""),
 explain=["Science grows when people ask questions, observe carefully, test ideas with experiments and share results. Ideas that fail a test are changed or dropped.","New tools such as the telescope and the microscope let people see what the eye cannot see and so changed science. Scientists in many countries, including India, built on each other's work over centuries.","Good scientists are curious, honest and open to being wrong. Scientific knowledge changes as better evidence arrives, and it helps us in health, farming, transport and communication."],
 terms=["observation","experiment","evidence","hypothesis"],
 narr=[("Science grows through questions, careful observation and experiments.","questions and tests"),("New tools like the telescope and microscope show us more of the world.","new tools"),("Scientists share results and build on each other's work.","sharing"),("Scientific ideas change when better evidence arrives.","evidence changes ideas")],
 ex=("Ravi thinks the Moon is bigger near the horizon. How can he test it?",[("He holds a coin at arm's length against the Moon when it is high and when it is near the horizon.","This is a fair measurement."),("He compares how much of the Moon the coin covers.","The coin is the same both times."),("It covers the same, so the Moon is not really bigger.","Testing beats guessing.")]),
 tb=("A friend says scientific ideas never change. How will you reply?",["They change when better evidence is found.","This is how science improves."],["Thinking science is a fixed list of facts."]),
 summary=["Science grows by questions, observation and tests.","New tools help us discover more.","Ideas change with better evidence."],
 q=[("mcq",1,"r1-grow","Science grows through","questions and experiments",[("guessing only","Ideas are tested."),("silence","Sharing helps science grow.")],"Testing ideas is central."),
    ("tf",1,"r1-share","Scientists share their results.",True,"True."),
    ("mcq",2,"r2-tool","Which tool helps us see very small things?","microscope",[("telescope","That helps see far things."),("ruler","A ruler measures length.")],"A microscope magnifies small objects."),
    ("tf",2,"r2-change","Scientific ideas can change with new evidence.",True,"True."),
    ("mcq",3,"r3-quality","A good scientist is","curious and honest",[("careless","Care is needed."),("closed to new ideas","Open minds are needed.")],"Honesty and curiosity matter."),
    ("short",3,"r3-tool","Name one tool that scientists use.",["telescope","microscope","thermometer","ruler","balance","stopwatch","computer"],"Many tools help observation."),
    ("mcq",4,"r4-evi","An idea is accepted in science when","evidence supports it",[("it sounds nice","Evidence decides."),("many people believe it","Evidence decides.")],"Tests give evidence."),
    ("tf",4,"r4-help","Science helps in health and farming.",True,"True.")]))
build(dict(S,ch="exploring-substances-acidic-basic-and-neutral",topic="acids-bases-and-indicators",name_en="Acids, bases and indicators",name_ta="அமிலம், காரம், நிறங்காட்டிகள்",
 objectives=["Tell acidic, basic and neutral substances apart","Use litmus and turmeric as indicators"],
 story=("The magic of turmeric","Anita spilled a little soap solution on her yellow turmeric-stained handkerchief. The yellow turned red.\n\"Magic!\" she said. Her teacher smiled. \"No, chemistry. Turmeric changes colour in a base like soap.\""),
 explain=["Substances can be acidic, basic or neutral. Lemon juice, vinegar and tamarind are acidic and taste sour. Soap, baking soda and lime water are basic and feel slippery. Water and salt solution are neutral.","We use indicators to test substances. Blue litmus turns red in an acid. Red litmus turns blue in a base. Neutral substances do not change litmus. Turmeric turns red in a base. China rose gives a colour change too.","Never taste unknown substances. Acids and bases can be harmful, so handle them carefully and wash your hands afterwards."],
 terms=["acid","base","neutral","indicator","litmus"],
 narr=[("Lemon, vinegar and tamarind are acids. They taste sour.","acids"),("Soap and baking soda are bases. They feel slippery.","bases"),("An indicator changes colour. Blue litmus turns red in an acid. Red litmus turns blue in a base.","litmus test"),("Never taste an unknown substance. Handle it with care.","safety")],
 ex=("Blue litmus paper dipped in lemon juice turns red. What does this tell us?",[("Blue litmus turns red only in an acid.","This is the rule."),("It turned red in lemon juice.","The test shows an acid."),("So lemon juice is acidic.","It also tastes sour.")]),
 tb=("A friend says every liquid changes litmus colour. How will you correct this?",["Neutral liquids such as pure water do not change litmus.","Only acids and bases do."],["Thinking all liquids are acids or bases."]),
 summary=["Acids are sour; bases are slippery; neutral substances change neither.","Indicators such as litmus show which is which.","Never taste unknown substances."],
 q=[("mcq",1,"r1-acid","Which is acidic?","lemon juice",[("soap solution","Soap is basic."),("pure water","Water is neutral.")],"Lemon juice is sour."),
    ("tf",1,"r1-soap","Soap solution is basic.",True,"True."),
    ("mcq",2,"r2-lit","Red litmus turns blue in a","base",[("acid","Acids turn blue litmus red."),("neutral substance","No change.")],"Bases turn red litmus blue."),
    ("tf",2,"r2-neut","A neutral substance changes the colour of litmus.",False,"False."),
    ("mcq",3,"r3-turm","Turmeric turns red in a","base",[("acid","Acids do not change it."),("neutral","No change.")],"Turmeric is also an indicator."),
    ("short",3,"r3-sour","Name one sour acidic food.",["lemon","vinegar","tamarind","curd","orange","tomato","amla"],"Sour foods are acidic."),
    ("mcq",4,"r4-safe","Which is a safe habit?","not tasting unknown substances",[("tasting to check","That is unsafe."),("mixing them","Do not mix unknown chemicals.")],"Some substances are harmful."),
    ("tf",4,"r4-ind","An indicator shows whether a substance is acidic or basic.",True,"True.")]))
build(dict(S,ch="electricity-circuits-and-their-components",topic="simple-electric-circuits",name_en="Simple electric circuits",name_ta="எளிய மின்சுற்றுகள்",
 objectives=["Name the parts of a simple circuit","Say why a circuit must be closed"],
 story=("The torch that would not glow","Meena's torch did not light. She opened it and found the battery had slipped so that it did not touch the metal strip.\nShe pushed it back and the bulb glowed.\n\"The path was broken,\" she said."),
 explain=["An electric circuit is a closed path along which electric current flows. A simple circuit has a cell or battery, a bulb, wires and a switch.","When the switch is on (closed), current flows from the cell through the wires and bulb and back, so the bulb glows. When the switch is off (open) the path is broken and the bulb does not glow.","Conductors such as metals let current pass. Insulators such as rubber, plastic and wood do not. Never touch mains electricity or play with sockets. Use only cells for experiments."],
 terms=["circuit","cell","switch","conductor","insulator"],
 narr=[("An electric circuit is a closed path for current. It has a cell, a bulb, wires and a switch.","parts of a circuit"),("When the switch is closed, current flows and the bulb glows.","closed circuit"),("When the switch is open, the path is broken and the bulb does not glow.","open circuit"),("Metals conduct. Rubber and plastic do not. Never touch mains electricity.","safety and conductors")],
 ex=("A bulb in a circuit does not glow. Give two things to check.",[("Check whether the switch is closed.","An open switch breaks the path."),("Check the wires, the cell and the bulb connections.","A loose wire breaks the path too."),("A closed, complete path makes the bulb glow.","Also check that the bulb is not fused.")]),
 tb=("A friend says a bulb will glow with just one wire to the cell. How will you explain?",["Current needs a complete closed path.","One wire does not make a loop."],["Thinking electricity needs only one connection."]),
 summary=["A circuit is a closed path with a cell, wires, a bulb and a switch.","The bulb glows only when the circuit is closed.","Metals conduct; rubber and plastic insulate."],
 q=[("mcq",1,"r1-closed","A bulb glows when the circuit is","closed",[("open","Open breaks the path."),("empty","It needs a complete path.")],"Current needs a complete loop."),
    ("tf",1,"r1-switch","A switch can open or close a circuit.",True,"True."),
    ("mcq",2,"r2-cond","Which is a good conductor?","copper wire",[("rubber","Rubber is an insulator."),("plastic","Plastic is an insulator.")],"Metals conduct."),
    ("tf",2,"r2-open","A bulb glows when the switch is open.",False,"False."),
    ("mcq",3,"r3-parts","Which is NOT part of a simple circuit?","a balloon",[("a cell","It supplies current."),("a bulb","It glows.")],"A circuit needs a source, wires, a bulb and a switch."),
    ("short",3,"r3-ins","Name one insulator.",["rubber","plastic","wood","glass","cloth","paper","thermocol"],"Insulators do not pass current."),
    ("mcq",4,"r4-safe","For experiments we should use","cells, not mains electricity",[("sockets","Sockets are dangerous."),("open wires","These are dangerous.")],"Cells are safe."),
    ("tf",4,"r4-loop","Current flows through a complete loop.",True,"True.")]))
build(dict(S,ch="the-world-of-metals-and-non-metals",topic="properties-of-metals-and-non-metals",name_en="Properties of metals and non-metals",name_ta="உலோகங்களும் அலோகங்களும்",
 objectives=["List physical properties of metals","Compare metals and non-metals"],
 story=("The goldsmith","Gopal watched a goldsmith beat a small piece of gold into a thin sheet and pull another piece into a fine wire.\n\"Why does gold not break?\" he asked. \"Because metals are malleable and ductile,\" the goldsmith said."),
 explain=["Metals are usually hard, shiny (lustrous) and good conductors of heat and electricity. They can be beaten into thin sheets (malleable) and drawn into wires (ductile). Many metals make a ringing sound when struck (sonorous). Examples are iron, copper, aluminium, gold and silver.","Non-metals such as carbon, sulphur, oxygen and nitrogen are usually dull, soft or brittle and are poor conductors. Many are gases.","Mercury is a metal that is liquid at room temperature. Graphite, a form of carbon, conducts electricity even though carbon is a non-metal. Metals are used for wires, vessels and tools; non-metals are used for fuels, fertilisers and more."],
 terms=["metal","non-metal","malleable","ductile","lustre"],
 narr=[("Metals are shiny and hard. They conduct heat and electricity.","metals: shiny, conduct"),("Metals can be beaten into sheets and drawn into wires. They make a ringing sound.","malleable, ductile, sonorous"),("Non-metals are usually dull and poor conductors. Many are gases.","non-metals"),("Mercury is a liquid metal. Graphite is a non-metal that conducts.","exceptions")],
 ex=("Why are electric wires made of copper and covered with plastic?",[("Copper is a good conductor and ductile, so it is drawn into wires.","Metal property."),("Plastic is an insulator, so it keeps the current from escaping.","Non-metal property."),("So the wire carries current safely.","Each material is chosen for its property.")]),
 tb=("A friend says all non-metals are gases. How will you correct this?",["Carbon and sulphur are solid non-metals.","Only some non-metals are gases."],["Generalising from a few examples."]),
 summary=["Metals are shiny, hard, malleable, ductile and conduct.","Non-metals are usually dull and poor conductors.","There are exceptions: mercury and graphite."],
 q=[("mcq",1,"r1-malle","A metal that can be beaten into sheets is","malleable",[("brittle","Brittle things break."),("dull","Dull means not shiny.")],"Gold is very malleable."),
    ("tf",1,"r1-cond","Metals are good conductors of electricity.",True,"True."),
    ("mcq",2,"r2-duct","Drawing a metal into wires shows it is","ductile",[("brittle","Brittle breaks."),("sonorous","That is a ringing sound.")],"Copper is ductile."),
    ("tf",2,"r2-merc","Mercury is a liquid metal.",True,"True."),
    ("mcq",3,"r3-non","Which is a non-metal?","sulphur",[("iron","Iron is a metal."),("copper","Copper is a metal.")],"Sulphur is a yellow solid non-metal."),
    ("short",3,"r3-name","Name one metal.",["iron","copper","aluminium","gold","silver","zinc","tin","lead","mercury","brass"],"Many metals are common."),
    ("mcq",4,"r4-sound","A metal that rings when struck is","sonorous",[("malleable","That is beating into sheets."),("ductile","That is drawing into wires.")],"Bells are made of metal."),
    ("tf",4,"r4-graph","Graphite is a non-metal that conducts electricity.",True,"True.")]))
